styles:
/* ===== Careers — single job posting (scoped) ===== */
.page-career .career-hero { padding-bottom: clamp(24px, 4vw, 48px); }
.page-career .career-back {
  display: inline-flex; align-items: center; gap: 8px;
  color: var(--grey-500); font-size: 15px; text-decoration: none;
  margin-bottom: clamp(22px, 3vw, 36px);
  transition: color .3s var(--ease), transform .3s var(--ease);
}
.page-career .career-back:hover { color: var(--red); }
.page-career .career-back .arrow {
  display: inline-grid; place-items: center;
  transition: transform .3s var(--ease);
}
.page-career .career-back:hover .arrow { transform: translateX(-3px); }

.page-career .career-hero__title {
  font-family: var(--font-display);
  font-size: clamp(40px, 7vw, 88px);
  line-height: 1.06; color: var(--grey-700); letter-spacing: -0.01em;
  margin-bottom: clamp(22px, 3vw, 34px);
}
.page-career .career-meta {
  display: flex; flex-wrap: wrap; gap: clamp(16px, 3vw, 40px);
  padding-top: clamp(20px, 2.4vw, 30px);
  border-top: 1px solid var(--line);
}
.page-career .career-meta__item { display: flex; flex-direction: column; gap: 6px; }
.page-career .career-meta__label {
  font-size: 13px; letter-spacing: .04em; text-transform: uppercase;
  color: var(--grey-500);
}
.page-career .career-meta__val {
  font-family: var(--font-display); font-weight: 600;
  font-size: clamp(16px, 1.3vw, 19px); color: var(--grey-900);
}

/* Readable measure */
.page-career .career-body { max-width: 760px; }
.page-career .career-block { margin-bottom: clamp(40px, 5vw, 64px); }
.page-career .career-block h2 {
  font-family: var(--font-display);
  font-size: clamp(26px, 3.4vw, 40px); color: var(--red);
  line-height: 1.1; margin-bottom: clamp(16px, 2vw, 24px);
}
.page-career .career-block p {
  color: var(--grey-700); font-size: clamp(16px, 1.2vw, 19px);
  line-height: 1.75; margin-bottom: 18px;
}
.page-career .career-block p:last-child { margin-bottom: 0; }
.page-career .career-list {
  list-style: none; padding: 0; margin: 0;
  display: flex; flex-direction: column; gap: 14px;
}
.page-career .career-list li {
  position: relative; padding-left: 30px;
  color: var(--grey-700); font-size: clamp(16px, 1.2vw, 19px);
  line-height: 1.65;
}
.page-career .career-list li::before {
  content: ""; position: absolute; left: 0; top: .55em;
  width: 9px; height: 9px; border-radius: 50%;
  background: var(--red);
}

.page-career .career-apply {
  margin-top: clamp(12px, 2vw, 24px);
  padding: clamp(28px, 4vw, 48px);
  background: var(--bg-alt); border: 1px solid var(--line);
  border-radius: var(--radius-lg);
}
.page-career .career-apply h2 { margin-bottom: clamp(14px, 2vw, 22px); }
.page-career .career-apply .btn-hello { margin-top: clamp(20px, 2.6vw, 30px); }
.page-career .career-allroles {
  display: inline-flex; align-items: center; gap: 9px;
  margin-top: clamp(28px, 4vw, 46px);
  color: var(--red); font-size: 16px; text-decoration: none;
}
.page-career .career-allroles .arrow {
  width: 30px; height: 30px; border-radius: 50%;
  border: 1.5px solid var(--red); color: var(--red);
  display: grid; place-items: center;
  transition: background .3s var(--ease), color .3s var(--ease), transform .3s var(--ease);
}
.page-career .career-allroles:hover .arrow {
  background: var(--red); color: #fff; transform: translateX(3px);
}
